mapper.select:
SELECT * FROM (

 WHERE tdm20_company_id = #{companyId}

   AND CAST(#{baseDate} AS date) BETWEEN tdm20_start_date AND COALESCE(tdm20_end_date, TO_DATE('29991231','yyyyMMdd'))


   AND tdm20_role_type = #{roleType}

) t
 WHERE CONCAT(role_name, role_type_name, overview) ILIKE #{searchText}
 ORDER BY role_name COLLATE "ko_KR.utf8"
        , role_type
        , role_type_etc_name COLLATE "ko_KR.utf8"
        , start_date


WHERE tdm20_role_id IN ( SELECT tdm51_role_id
                           FROM tdm51_chck_org
                                INNER JOIN tdm58_chck_appr_step ON tdm58_chck_org_id = tdm51_chck_org_id
                          WHERE tdm51_company_id  = #{companyId}
                            AND tdm51_check_ym    = #{checkYm}
                            AND tdm58_appr_emp_id = #{personId}
                            AND EXISTS ( SELECT 1
                                           FROM tdm52_chck_manl
                                          WHERE tdm52_chck_org_id = tdm51_chck_org_id ) )
  AND tdm20_role_nm ILIKE #{searchText}
ORDER BY tdm20_role_nm COLLATE "ko_KR.utf8"

SELECT COUNT(*)
  FROM tdm30_role_allc
 WHERE tdm30_role_id = #{roleId}

SELECT COUNT(*)
  FROM tdm20_role
 WHERE tdm20_ceo_role_id = #{roleId}

mapper.update:
UPDATE tdm20_role
   SET tdm20_role_nm           = #{row.roleName}
     , tdm20_role_type         = #{row.roleType}
     , tdm20_role_type_etc_nm  = #{row.roleTypeEtcName}
     , tdm20_overview          = #{row.overview}
     , tdm20_start_date        = #{row.startDate}
     , tdm20_end_date          = #{row.endDate}
     , tdm20_ceo_role_id       = #{row.ceoRoleId}
     , tdm20_upd_nm            = #{updName}
     , tdm20_upd_date          = f_sysdate()
 WHERE tdm20_role_id = #{row.roleId}
   AND tdm20_company_id = #{companyId}

UPDATE tdm20_role
   SET tdm20_ceo_role_id = #{ceoRoleId}
     , tdm20_upd_nm      = #{updName}
     , tdm20_upd_date    = f_sysdate()
 WHERE tdm20_role_id = #{roleId}
   AND tdm20_company_id = #{companyId}

