mapper.select:
SELECT tdm23_role_relate_org_id AS role_relate_org_id , tdm23_role_id AS role_id , tdm23_org_id AS org_id , org00_org_cd AS org_code , org00_kor_nm AS org_name FROM tdm23_role_relate_org INNER JOIN tdm20_role ON tdm20_role_id = tdm23_role_id INNER JOIN getOrg(#{companyId}, CAST(#{stdDate} AS date)) ON org00_org_id = tdm23_org_id WHERE tdm23_role_id = #{roleId}
AND NOT EXISTS ( SELECT 1 FROM tdm09_appr_step WHERE tdm09_company_id = tdm20_company_id AND tdm09_role_id = tdm23_role_id AND tdm09_org_id = tdm23_org_id AND tdm09_type_cd = 'C' )
AND org00_kor_nm ILIKE #{searchText}
ORDER BY org00_org_cd

SELECT COUNT(*)
  FROM getOrg(#{companyId}, CAST(#{stdDate} AS date))
 WHERE org00_org_id = #{orgId}

